window.__BUNDLE__={"generatedAt":"2026-08-20T16:03:44.346290+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-08-13","archiveCutoff":"2021-08-21","addedToday":0,"historyTotal":7051,"topicCounts":{"Multi-Agent":1497,"Evaluation":3478,"Planning":681,"Memory":148,"Code Agent":429,"Interpretability":226,"Agentic Search":594,"RL for LLM":620,"Reasoning":2292,"Hallucination":421,"Post-Training":1168,"Alignment":939,"World Model":74,"Tool Use":958,"Agent Safety":1884,"Computer Use":191,"Reflection":329,"VLM Training":269,"LLM Training":769,"Fine-tuning":1042,"Multimodal Agent":36,"Agent Framework":566,"Error Attribution":62,"Data Engine":166},"count":36,"recentTotal":914,"archiveCount":0,"archiveTotal":6136,"sources":{"hf":121,"arxiv":784,"semanticScholar":9},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":["zero_new_today"],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"id":"arxiv:2608.13558","source":"hf","title":"OmniScientist: An Omni-Modal Omni-Discipline AI Scientist","authors":["Bobo Li","Hao Fei","Tianjie Ju","Mong-Li Lee","Wynne Hsu"],"tags":["Reasoning"],"date":"2026-08-20","arxiv":"https://arxiv.org/abs/2608.13558","url":"https://arxiv.org/abs/2608.13558","pdf":"https://arxiv.org/pdf/2608.13558.pdf","topics":["Reasoning"],"hfUrl":"https://huggingface.co/papers/2608.13558","upvotes":81,"abstract":"Recent advances in foundation models have enabled AI scientists to automate increasingly complete research workflows, from hypothesis generation and code execution to manuscript preparation. Yet workflow coverage alone does not provide access to the full evidence on which scientific discovery depends. Existing systems typically reason over text, code, labels, or precomputed summaries, leaving scientifically decisive spatial, temporal, cross-channel, and procedural relations unavailable to the agent. We introduce OmniScientist, an end-to-end, omni-modal AI scientist that conducts multidisciplinary research directly from heterogeneous raw evidence. A perception layer and 3 autonomous agents for ideation, experiment, and writeup operate within a deterministic pipeline, allowing observations to shape research questions, experimental decisions, and final claims throughout the research lifecyc"},{"id":"arxiv:2608.14229","source":"hf","title":"The More Popular, The Harder to Forget: Adaptive Popularity for LLM Unlearning","authors":["Anna Borisiuk","Andrey Savchenko","Alexander Panchenko","Elena Tutubalina"],"tags":["LLM Training","Evaluation"],"date":"2026-08-20","arxiv":"https://arxiv.org/abs/2608.14229","url":"https://arxiv.org/abs/2608.14229","pdf":"https://arxiv.org/pdf/2608.14229.pdf","topics":["LLM Training","Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.14229","upvotes":11,"abstract":"Popular facts are memorised more deeply during pretraining and resist removal longer than rare ones, yet existing LLM unlearning methods apply uniform gradient pressure regardless of training-data frequency. We propose the AdaPop (Adaptive Popularity) method, which combines local token confidence with a per-fact popularity-dependent exponent derived from an external proxy (e.g., Wikidata sitelinks, LLM-as-Judge), and automates the forget-retain balance via a dual-ascent controller that adjusts the retain penalty each epoch. Across three model families and two benchmarks, AdaPop leaks ~5x less forgotten content than competing methods under paraphrased queries and ~1.6x less under adversarial reformulations. We support our analysis with internal metrics: under our method, forget-set hidden states move further from the pre-unlearning model's states than under other methods, while retain-set"},{"id":"arxiv:2608.18115","source":"hf","title":"Temporal Multi-Signal Fusion for Token-Level Hallucination Detection","authors":["Igor Itkin"],"tags":["Hallucination"],"date":"2026-08-20","arxiv":"https://arxiv.org/abs/2608.18115","url":"https://arxiv.org/abs/2608.18115","pdf":"https://arxiv.org/pdf/2608.18115.pdf","topics":["Hallucination"],"hfUrl":"https://huggingface.co/papers/2608.18115","upvotes":2,"abstract":"Token-level hallucination detectors score each token independently from a single signal, and fail exactly when the generating model is confidently wrong. This paper instead treats hallucination as a temporally extended span and detects it by sequence labeling: each token is scored from a 33-dimensional feature stream that fuses text statistics, Natural Language Inference (NLI) entailment, and language model surprisal, with no access to model internals. A Bidirectional Gated Recurrent Unit (BiGRU) over these features reaches an AUC of 0.840 on RAGTruth (10 seeds), an 11-point gain over an independent logistic-regression baseline (p = 0.002, Wilcoxon signed-rank). A controlled decomposition attributes most of the gain to temporal order rather than model capacity: evidence propagates from confident positions to ambiguous neighbors within a span. The same 0.845 ceiling recurs across recurren"},{"id":"arxiv:2608.14036","source":"hf","title":"Demystifying Agent Skills: Why They Work-Until They Don't","authors":["Zhiyuan Jiang","Fangrui Huang","Hanwen Xing","Xander Wu","Yipeng Gao","Rui Cao","Mengdi Wang","Shilong Liu","Yijiang Li"],"tags":["Agent Safety","Evaluation"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.14036","url":"https://arxiv.org/abs/2608.14036","pdf":"https://arxiv.org/pdf/2608.14036.pdf","topics":["Agent Safety","Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.14036","upvotes":152,"abstract":"Skills have emerged as a practical and effective approach for enhancing LLM agents at inference time through structured packages of knowledge. However, existing evaluations largely measure whether skills improve aggregated task success, leaving a more fundamental question underexplored: \\emph{\\textbf{When do skills help, why do they work, and where do they fail?}} Through controlled experiments across various benchmarks, agent harnesses and LLMs, we isolate the effects of representation, outcome annotation, retrieval difficulty, and cross-framework robustness of skills. To further answer this question, we design a contrastive study that combines controlled quantitative experiments with paired trajectory analysis. We normalize 8,135 trial records from controlled experiments and retain 238 valid unique labels from 240 open-coded records. We consolidate these observations into a taxonomy of"},{"id":"arxiv:2608.17310","source":"hf","title":"Agentic ESOpt: Fine-Tuning Long-Horizon LLM Agents with Minimal GPU Requirements","authors":["Zhi Zheng","Rongsheng Chen","Yunpeng Ba","Zhenkun Wang","Yee Whye Teh","Wee Sun Lee"],"tags":["Reasoning","Fine-tuning","RL for LLM"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.17310","url":"https://arxiv.org/abs/2608.17310","pdf":"https://arxiv.org/pdf/2608.17310.pdf","topics":["Reasoning","Fine-tuning","RL for LLM"],"hfUrl":"https://huggingface.co/papers/2608.17310","upvotes":96,"abstract":"Reinforcement Learning (RL) has been promising in single-turn LLM fine-tuning. However, long-horizon agentic reasoning introduces increasingly branching interactions and sparse rewards, exposing several limitations of RL: its heavyweight backpropagation-based training stack makes it impractical to fine-tune larger LLMs, and longer-horizon trajectories make credit assignment in RL substantially harder. This paper argues that evolution strategies (ES) can be a better choice for fine-tuning long-horizon LLM agents. Compared with agentic RL, ES offers three key advantages: 1) Model Scalability: ES enables full-parameter optimization with only minimal, inference-level GPU memory, making it possible to fine-tune large LLMs. 2) Flexibility: its lightweight, black-box feedback interface makes ES fine-tuning easy to compose with prompt-space evolution (e.g., skill optimization & test-time compute"},{"id":"arxiv:2608.17271","source":"hf","title":"ASI-Bench: At the Dawn of Artificial Superintelligence","authors":["Junwei Zhou","Zhen Sun","Binyu Li","Jiangyu Zhou","Yuexi Pan","Hengyu Wang","Honghe Ren","Xiaohan Jia","Xueyang Zhou","Xiaoyu Cao","Yongchao Chen","Yuanning Feng","Junhao Wu","Cheng Zhang","Sijia Chen","Haoyu Xue","Chengsong You","Huan Wang","Koutian Wu","Peigan Gao","Jiakun Wu","Wenzhe Li","Ergan Shang","Qingyuan Zheng","Jingjing Zhou","Ruixuan Jia","Yan Xu","Hongrui Zhang","Xiao-Han Ma","Zhengxiang Cheng","Yuexing Hao","Liting Mai","Xianglin Ji","Wenjun Zhang","Zhuofan Chen","Yixiao Huang","Chi Wang","Wenyue Hua","Yilun Hao","Yuantao Zhai","Ziyan Zhao","Jingyan Xie"],"tags":["Evaluation"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.17271","url":"https://arxiv.org/abs/2608.17271","pdf":"https://arxiv.org/pdf/2608.17271.pdf","topics":["Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.17271","upvotes":55,"abstract":"Artificial superintelligence (ASI) requires AI to move beyond mastering existing knowledge toward exploring the unknown, creating new knowledge, and turning new ideas into verifiable results. However, the capabilities of today's AI systems are still largely built on learning, compressing, and applying existing human knowledge. Accordingly, existing benchmarks primarily test whether AI can produce correct answers based on learned knowledge, or whether it can complete tasks under extensive human guidance. We therefore introduce ASI-Bench, the first benchmark to jointly evaluate AI systems' capabilities of innovative exploration and autonomous scientific execution across general research domains, and the first to progressively withdraw human methodological guidance within the same research project to test how far AI can proceed on its own. Built by over 40 experts with the cost of 31,000+ h"},{"id":"arxiv:2608.17512","source":"hf","title":"Embodied-Navigator: Point, Think, Memorize, and Align for Efficient Navigation","authors":["Hongyan Feng","Sunlai Chen","Xuanyu Liu","Miao Pan","Yangfan Xie","Yuxiang Cui","Zhongxiang Zhou","Rong Xiong","Wenqi Zhang","Jianwei Yin","Yueting Zhuang","Xuhong Zhang"],"tags":["Post-Training","LLM Training","VLM Training","Reasoning","Planning"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.17512","url":"https://arxiv.org/abs/2608.17512","pdf":"https://arxiv.org/pdf/2608.17512.pdf","topics":["Post-Training","LLM Training","VLM Training","Reasoning","Planning","Memory","Alignment"],"hfUrl":"https://huggingface.co/papers/2608.17512","upvotes":46,"abstract":"Although Large Vision-Language Models (VLMs) have significantly advanced embodied navigation, their direct deployment remains challenging, as existing methods often force VLMs into unnatural action spaces that misalign with their 2D pre-training priors, compounded by rigid reasoning schedules and inefficient memory management. To overcome these limitations, we propose TAMP-Nav, a unified framework for efficient embodied navigation. First, we introduce a Pixel-to-3D Action Formulation (Point) that reformulates navigation into 2D visual prompting. Specifically, the VLM merely selects 2D pixels, which are then projected into 3D coordinates for a low-level SLAM controller. This design naturally aligns embodied execution with the VLM's inherent 2D visual capabilities. Second, we propose an integrated Selective Reasoning and Anchor-Trajectory Memory mechanism (Think and Memorize), which dynami"},{"id":"arxiv:2608.12313","source":"hf","title":"AVA-Encoder: Towards Agent-Native Video Representation Learning","authors":["Chuyue Li","Jinpeng Yu","Haozhe Wang","Tian Xueyun","Zhijing Zhang","Bingnan Li","Shuqi Gu","Kan Ren","Jiaming Liu","Ruihua Hua"],"tags":["Reasoning","Evaluation"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.12313","url":"https://arxiv.org/abs/2608.12313","pdf":"https://arxiv.org/pdf/2608.12313.pdf","topics":["Reasoning","Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.12313","upvotes":40,"abstract":"Creative agents still lack an effective way to learn from high-quality human films, limiting their ability to produce cinematic-grade videos. A key challenge is the absence of a structured video representation that is both faithful to film content and directly usable for agentic reasoning and manipulation. To address the challenge, we propose the Agentic Video Auto-Encoder (AVA-Encoder), a framework for learning agent-native video representations via agentic auto-encoding. AVA-Encoder transforms a video into a knowledge graph (KG) representation and then reconstructs it back into video. Its hierarchy and state nodes store structured text, while a linked asset layer holds generated images, audio, and video. Typed edges preserve the relations between these text descriptions and assets in a form that agents can easily understand, query, and edit. The video reconstruction differences drive a"},{"id":"arxiv:2608.17528","source":"hf","title":"Agent Lightning v1.0: Towards Harnessed Agentic RL","authors":["Zhiyuan He","Siwei Zhang","Zhiwen Zhou","Yuqing Yang","Yu Kang","Yuge Zhang","Luna K. Qiu","Tin Yan Tsui","Jiahang Xu","Chong Luo"],"tags":["Post-Training","Code Agent"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.17528","url":"https://arxiv.org/abs/2608.17528","pdf":"https://arxiv.org/pdf/2608.17528.pdf","topics":["Post-Training","Code Agent"],"hfUrl":"https://huggingface.co/papers/2608.17528","upvotes":22,"abstract":"Modern agents operate inside agent harnesses that manage tools, context, and control flow, making the harness a critical part of the agent system. Our original Agent Lightning introduced a disaggregated architecture that connects arbitrary agents to RL training through an LLM endpoint proxy, an approach later adopted by frameworks such as verl Uni-Agent, AReaL 2.0, slime, and Polar. We refer to this paradigm as harnessed agentic RL, where the deploy-time harness directly participates in model post-training. Harnessed agentic RL differs fundamentally from traditional agentic RL: the harness, rather than the training engine, owns the environment interaction loop, while the trainer observes only sequences of LLM request-response pairs. This introduces challenges in retokenization, sample merging, advantage calculation, loss normalization, and backend scheduling, which can substantially affe"},{"id":"arxiv:2608.17067","source":"hf","title":"DiSCO: Defending text-to-image generation through distribution-guided contrastive prompt optimization","authors":["Tong Zhang","Motasem Alfarra","Carlos Hinojosa","Christos Louizos","Bernard Ghanem"],"tags":["Agent Safety","Evaluation","Fine-tuning"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.17067","url":"https://arxiv.org/abs/2608.17067","pdf":"https://arxiv.org/pdf/2608.17067.pdf","topics":["Agent Safety","Evaluation","Fine-tuning"],"hfUrl":"https://huggingface.co/papers/2608.17067","upvotes":19,"abstract":"As text-to-image generative models advance, they raise critical safety concerns, particularly the generation of Not-Safe-For-Work (NSFW) content such as violence and nudity, further exacerbated by red-teaming adversarial attacks. Existing defenses predominantly operate under white-box assumptions, relying on text encoder optimization, weight editing, or inference-time intervention, and fundamentally cannot scale to proprietary models. Black-box alternatives based on LLM prompt rewriting offer broader applicability, yet fail in a critical regime we identify as the \\textit{benign adversarial} problem: prompts that are linguistically safe but still trigger harmful generation due to the model's learned data distribution. We propose DiSCO, a zero-shot, strictly black-box defense that operates entirely at the prompt level as a plug-and-play module, requiring no model retraining, fine-tuning, o"},{"id":"arxiv:2608.17566","source":"hf","title":"CoinVE-200K: A Large-Scale High-Quality Dataset for Compositional Instruction-Guided Video Editing","authors":["Fuchen Long","Cong Wang","Zitao Gao","Wenhao Zhong","Yu Cheng","Xiaolu Hou","Yan Li","Xiao Cao","Xinlong Sun","Xi Chen","Yu Liu"],"tags":["Hallucination","Evaluation"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.17566","url":"https://arxiv.org/abs/2608.17566","pdf":"https://arxiv.org/pdf/2608.17566.pdf","topics":["Hallucination","Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.17566","upvotes":15,"abstract":"The quality and diversity of instruction-based video editing datasets are steadily improving, yet existing datasets mainly focus on single editing operations and fall short in supporting compositional instruction-guided video editing. In particular, multiple editing intents must be jointly understood and faithfully executed within the same video. To address this issue, we introduce CoinVE-200K, a large-scale, high-quality dataset for Compositional Instruction-Guided Video Editing. CoinVE-200K contains 1080p video-editing pairs of up to 201 frames, covering diverse compositional scenarios where each sample involves 2 to 5 atomic editing operations. The instructions target humans, objects, and backgrounds, and cover edit types such as addition, removal, modification, and stylization. All samples are built through a carefully designed generation and filtering pipeline to ensure instruction "},{"venue":"arXiv","id":"arxiv:2608.15008","source":"hf","title":"Harness the Memory: A Holistic Evaluation of Memory Substrates in Memory Agents","authors":["Wei-Chieh Huang","Weizhi Zhang","Yuchen Wu","Yankai Chen","Eric Hanchen Jiang","Wooseong Yang","Yiwei Yang","Henry Peng Zou","Hanrong Zhang","Ying Nian Wu","Haolun Wu","Kai-Wei Chang","Philip S. Yu","Xue Liu","Aylin Caliskan"],"tags":["Memory","Evaluation"],"date":"2026-08-19","published":"2026-08-15","arxiv":"https://arxiv.org/abs/2608.15008","url":"https://arxiv.org/abs/2608.15008","pdf":"https://arxiv.org/pdf/2608.15008.pdf","publicationKind":"preprint","topics":["Memory","Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.15008","upvotes":13,"abstract":"Memory is becoming core infrastructure for long-horizon LLM agents, yet existing evaluations offer limited guidance on which memory substrate, namely the underlying medium in which memory is represented and stored, should be used under different operating regimes. We present a controlled harness evaluation of memory substrates for memory-augmented agents, covering dense and sparse indices, text records, structural stores, hierarchical stores, refinement-based memories, parametric updates, and activation-compatible context mechanisms. Across three backbone models and four benchmark suites spanning user-centric question answering and agent-centric decision-making, we instrument 26 performance and efficiency metrics under a unified harness. Our results show that no single substrate consistently dominates: broad retrieval benefits long-context factual QA, while excessive retrieval can harm s"},{"id":"arxiv:2608.18076","source":"hf","title":"From Corpora to Co-Evolving Capabilities: Capability-Centric Data Design for Generalist Image Generation","authors":["Xingjian Wang","Zhao Wang","Taihang Hu","Jun Zheng","Qing Jin","Qinye Zhou","Zhengtao Wu","Yongchao Du","Zuan Gao","Chao Lin","Yefeng Shen","Xiaoli Xu","Zhengze Xu","Hao Yan","Yuhang Yu","Mingzhou Zhang","Mengting Chen"],"tags":["Evaluation","Data Engine"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.18076","url":"https://arxiv.org/abs/2608.18076","pdf":"https://arxiv.org/pdf/2608.18076.pdf","topics":["Evaluation","Data Engine"],"hfUrl":"https://huggingface.co/papers/2608.18076","upvotes":11,"abstract":"Large-scale image generation has benefited from advances in data scale, quality, rebalancing, and recaptioning, yet conventional pipelines typically optimize task-specific datasets in isolation. A central challenge is not only how to curate each task-specific corpus, but also how to organize heterogeneous supervision according to the dependencies among generative capabilities. We present a capability-driven data infrastructure that couples capability-specific supervision construction with capability-aligned curriculum scheduling. Its three specialized yet interoperable data engines build complementary relational supervision for text-image grounding, inter-image transformation, and image-knowledge association, while caption experts align T2I and editing supervision across tasks and granularities. A multi-stage curriculum jointly evolves task composition, visual-concept distribution, data "},{"venue":"arXiv","id":"arxiv:2608.17597","source":"hf","title":"HarnessRisk: A Lifecycle-Oriented Benchmark for Agent Harness Safety","authors":["Yajing Bai","Jinhao Duan","Jie Peng","Xianfeng Wu","Sijia Liu","Song Wang","Tianlong Chen"],"tags":["Agent Safety","Evaluation"],"date":"2026-08-19","published":"2026-08-18","arxiv":"https://arxiv.org/abs/2608.17597","url":"https://arxiv.org/abs/2608.17597","pdf":"https://arxiv.org/pdf/2608.17597.pdf","publicationKind":"preprint","topics":["Agent Safety","Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.17597","upvotes":8,"abstract":"Large language models are increasingly deployed through agent harnesses that manage tools, extensions, persistent state, permissions, and external actions. Existing safety benchmarks mainly target individual attack mechanisms or a limited subset of operational settings, making it difficult to compare how safety failures emerge across different harness responsibilities. We present HarnessRisk, a lifecycle oriented benchmark that organizes agent harness safety into six operational phases including Harness Configuration, Capability Extension, Runtime Operation, State Persistence, Action Control, and Incident Recovery. HarnessRisk contains 128 sandboxed cases, each pairing a benign user objective with an adversarial instruction embedded in an untrusted workflow artifact. We evaluate each trajectory using Utility, Attack Success Rate, Persistence, and Detection. Across three harnesses, six la"},{"id":"arxiv:2608.17800","source":"hf","title":"StartupBench: Benchmarking General-Purpose Agents on Market-Validated End-to-End Workflows","authors":["Liya Zhu","Xin Ma","Tao Liu","Haodong Wang","Ge Zhang","Jingzhe Ding","Qingshui Gu","Yongjie Zhong","Jinxiang Meng","Yuan Gao","Yunqiu Zhou","Hao Zhu","Jifeng He","Yongzhi Liao","Xinyi Zhang","Chaoxin Li","Yi Zhu","Xi Lin","Duju Zeng","Xiang Gao","Wen Zhang","Yunyang Wang","Duo Wang","Huan Zhou","Zuo Wang","Jin Chen","Kaiyuan Zhang","Chuqian Yu","Tianhao Yu","Longxiang Liu","Jianbo Xue","Huimin Che","Jiahao Wang","Yujia Qin","Jiaheng Liu","Shen Yan","Xiaolong Chang","Wenhao Huang"],"tags":["Evaluation"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.17800","url":"https://arxiv.org/abs/2608.17800","pdf":"https://arxiv.org/pdf/2608.17800.pdf","topics":["Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.17800","upvotes":8,"abstract":"Recent advances in Large Language Models(LLMs) and agents have substantially improved the ability of AI systems to execute complex tasks. Yet existing benchmarks largely rely on researcher-selected tasks, leaving uncertain whether such progress extends to the work that real-world users actually demand from AI systems. We introduce \\textbf{StartupBench}, an E2E agent benchmark grounded in market-validated AI startup products. Rather than defining tasks from pre-defined assumptions about useful agent capabilities, we systematically study AI products with demonstrated adoption, together with their product workflows and users, to identify real-world tasks for which AI has established practical demand across diverse professional domains. We translate these workflows into complete deliverable-oriented tasks and evaluate them with fine-grained rubrics capturing their complex requirements. Acros"},{"id":"arxiv:2608.16002","source":"hf","title":"From Sequence to Structure: Relational Uncertainty Propagation for LLM Agents","authors":["Zhengzhao Ma. Boxi Cao","Yaojie Lu","Hongyu Lin","Xianpei Han","Le Sun"],"tags":["Error Attribution","Reasoning","Evaluation","Alignment"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.16002","url":"https://arxiv.org/abs/2608.16002","pdf":"https://arxiv.org/pdf/2608.16002.pdf","topics":["Error Attribution","Reasoning","Evaluation","Alignment"],"hfUrl":"https://huggingface.co/papers/2608.16002","upvotes":6,"abstract":"Reliable uncertainty quantification (UQ) is essential for deploying large language model (LLM) agents in complex interactive environments. Existing UQ methods largely rely on local signals, such as token probabilities, predictive entropy, or per-step confidence, and therefore overlook the long-range dependencies through which errors accumulate across an execution trajectory. As a result, they may fail to identify agent failures whose causes originate several reasoning or interaction steps before the final answer. We propose RUPA (Relational Uncertainty Propagation for Agents), a trajectory-level UQ framework for LLM agents. RUPA represents an execution history as a directed trajectory graph in which reasoning states, tool interactions, and environment feedback are nodes connected by temporal and semantic dependency edges. It then propagates uncertainty over this graph to capture how exec"},{"id":"arxiv:2608.14221","source":"hf","title":"MathForm: Scaling Mathematical Autoformalization with Knowledge Retrieval and Verification-Guided Refinement","authors":["Lushi Pu","Weiming Zhang","Xinheng Xie","Zixuan Fu","Bingxiang He","Hengyu Zhao","Hongya Lyu","Xin Li","Jie Zhou","Yudong Wang"],"tags":["LLM Training","Evaluation","Fine-tuning","Reflection"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.14221","url":"https://arxiv.org/abs/2608.14221","pdf":"https://arxiv.org/pdf/2608.14221.pdf","topics":["LLM Training","Evaluation","Fine-tuning","Reflection"],"hfUrl":"https://huggingface.co/papers/2608.14221","upvotes":6,"abstract":"Autoformalization is commonly framed as translating natural-language mathematical statements into machine-verifiable formal languages such as Lean 4. However, faithful formalization requires more than translation. Models must map mathematical concepts to the complex hierarchy of types and definitions in formal libraries such as Mathlib, while ensuring that generated statements preserve the meaning of the source propositions. Existing approaches struggle because they rely heavily on the model's parametric memory for library-specific knowledge, while common data construction pipelines often resort to filtering single-pass outputs and lack mechanisms for feedback-driven revision. To address these challenges, we introduce MathForm, an autoformalization framework for constructing verified training data through Mathlib knowledge retrieval and verification-guided iterative refinement. Before ge"},{"id":"arxiv:2608.16393","source":"hf","title":"Security Assessment of DeepSeek Harness with A.I.G: Evaluating Resistance to Indirect Prompt Injection","authors":["Zonghao Ying","Xiangfan Wu","Huiyu Wu","Xing Zheng","Huangsheng Cheng","Xiaorong Shi","Jing Guo"],"tags":["Agent Safety"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.16393","url":"https://arxiv.org/abs/2608.16393","pdf":"https://arxiv.org/pdf/2608.16393.pdf","topics":["Agent Safety"],"hfUrl":"https://huggingface.co/papers/2608.16393","upvotes":5,"abstract":"We assess indirect prompt injection in DeepSeek Harness (DSH), using AI-Infra-Guard (A.I.G) to construct tests, deliver controlled taint, execute DSH, collect traces, and judge outcomes. The study covers 14,560 controlled executions over 16 indirect-content channels, text and file carrier modes, 35 payload objectives, one unmodified baseline, and 12 attack methods. The experiment preserves DSH's agent loop, tool registry, model adapter, and session-event path; source tools and sensitive sinks are local fixtures, so attempted actions are recorded without external side effects. We evaluate each trace with a deterministic rule-based judge, \\JudgeR{} (RuleJudge), and a semantic LLM-based judge, \\JudgeL{} (LLMJudge). The strongest observed attack success rates are 17.0% under \\JudgeL{} for fake-completion attack in text mode, 25.5% under \\JudgeR{} for hidden Unicode in file mode, and 16.0% un"},{"id":"arxiv:2608.17050","source":"hf","title":"Cross-Model Memory Transfer via Target-Side Reader Adaptation","authors":["Mingyuan Li","Guangsheng Yu","Xu Wang","Shaoxiong Ji"],"tags":["Alignment"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.17050","url":"https://arxiv.org/abs/2608.17050","pdf":"https://arxiv.org/pdf/2608.17050.pdf","topics":["Alignment"],"hfUrl":"https://huggingface.co/papers/2608.17050","upvotes":4,"abstract":"Methods for improving knowledge use in large language models typically fall into two regimes. Non-parametric retrieval offers flexible access to external knowledge, but adds retrieval latency, context overhead, and only shallow integration with the backbone. Parametric adaptation is efficient at inference time, but entangles knowledge with model weights and can be hard to update, audit, or transfer. Engram-style hashed memory occupies a middle regime: it stores learned information in an external, addressable table, yet consumes that table through a small learned reader. This raises a basic question: when such a memory is moved across backbones, what matters more, the frozen memory itself or the target-side reader? We study this question through cross-model frozen-memory extraction, in which a memory trained on a source model is frozen and attached to a different target model, with only a"},{"venue":"arXiv","id":"arxiv:2608.17975","source":"hf","title":"aDSL: Agentic 3D Creation via Joint Agent-Program Design","authors":["Rui-Huan Wang","Si-Tong Wei","Jia-Qi He","Heng-Yi Wei","Baoquan Chen","Peng-Shuai Wang"],"tags":["Multi-Agent","Reasoning","Interpretability"],"date":"2026-08-19","published":"2026-08-18","arxiv":"https://arxiv.org/abs/2608.17975","url":"https://arxiv.org/abs/2608.17975","pdf":"https://arxiv.org/pdf/2608.17975.pdf","publicationKind":"preprint","topics":["Multi-Agent","Reasoning","Interpretability"],"hfUrl":"https://huggingface.co/papers/2608.17975","upvotes":3,"abstract":"Programmatic representations provide a compelling paradigm for 3D content creation, enabling fine-grained edits, interpretability, and explicit structural control. Yet, agentic workflows that rely on large language models (LLMs) to author 3D programs remain brittle, often failing to translate high-level intent into consistent low-level geometry. We attribute this fragility to a mismatch between existing programmatic interfaces and the reasoning strengths of LLMs, which favor semantic structure and spatial relations over fragile numeric choices. In this paper, we jointly design an Agent-centric Domain-Specific Language (aDSL) and a role-specialized multi-agent system to close this gap. aDSL bridges semantic logic and geometric constraints by emphasizing composability and spatial reasoning; it enables agents to manipulate geometry through relational operators instead of brittle absolute co"},{"id":"arxiv:2608.18580","source":"hf","title":"FACET: Preserving Source Intent and Executable State in Terminal Task Synthesis","authors":["Kou Shi","Zun Wang","Qisheng Su","Shiting Huang","Ziao Zhang","Zhen Fang","Qingnan Ren","Jin Liu","Yu Zeng","Yiming Zhao","Lin Chen","Zehui Chen","Feng Zhao"],"tags":["Alignment","Fine-tuning"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.18580","url":"https://arxiv.org/abs/2608.18580","pdf":"https://arxiv.org/pdf/2608.18580.pdf","topics":["Alignment","Fine-tuning"],"hfUrl":"https://huggingface.co/papers/2608.18580","upvotes":2,"abstract":"Training terminal agents requires scalable executable supervision, yet synthesizing high-quality terminal tasks remains challenging. Each task couples an instruction, an initialized environment, a reference solution, and an executable verifier; if these artifacts are generated from inconsistent assumptions, the resulting task may be unsolvable or incorrectly evaluated. Meanwhile, multi-stage synthesis can discard the goals, dependencies, state transitions, and procedural constraints encoded in the original sources. We present FACET (Fine-grained Agentic Construction of Executable Tasks), a framework that addresses both information preservation and cross-artifact consistency. FACET reconstructs related agent skills into coherent, information-rich scenarios, then realizes and repairs the execution environment before generating the final task artifacts. The resulting container state serves "},{"id":"arxiv:2608.16793","source":"hf","title":"PixRestore: Unified Image Restoration via Pixel Diffusion Transformer","authors":["Lingchen Sun","Rongyuan Wu","Xiangtao Kong","Jixin Zhao","Qiaosi Yi","Yujing Sun","Shuaizheng Liu","Zhengqiang Zhang","Lei Zhang"],"tags":["LLM Training","Evaluation"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.16793","url":"https://arxiv.org/abs/2608.16793","pdf":"https://arxiv.org/pdf/2608.16793.pdf","topics":["LLM Training","Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.16793","upvotes":1,"abstract":"Unified image restoration (UIR) aims to recover high-quality (HQ) content from low-quality (LQ) images with different degradations using a single model. Most recent methods adapt large pretrained text-to-image (T2I) latent diffusion models for their strong capacity and generative priors. However, the variational autoencoder (VAE) in latent T2I models may discard restoration-sensitive details, while the open-ended synthesis prior can introduce content-inconsistent artifacts. We present PixRestore, a VAE-free pixel-space Diffusion Transformer (DiT) for UIR, where the diffusion backbone is trained entirely from scratch, without relying on T2I pretraining. PixRestore performs flow matching directly on patchified pixels, preserving fine-grained details while keeping the token sequence tractable. To adapt to different degradations, PixRestore learns to predict the reliability of layer features"},{"id":"arxiv:2608.12944","source":"hf","title":"CardioState-JEPA: Delay-Aware Cross-Modal Learning of a Shared Cardiac Representation","authors":["Hamza Shafiq","Hung Manh Pham","Bin Zhu","Pan Zhou","Jun Hu","Aaqib Saeed"],"tags":["LLM Training","Evaluation"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.12944","url":"https://arxiv.org/abs/2608.12944","pdf":"https://arxiv.org/pdf/2608.12944.pdf","topics":["LLM Training","Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.12944","upvotes":1,"abstract":"Electrocardiography (ECG), photoplethysmography (PPG), and phonocardiography (PCG) provide complementary views of the same cardiac cycle, yet existing cardiac foundation models are trained for a single sensing modality, leaving the shared physiology across sensors unexploited. We introduce CardioState-JEPA, a cardiac foundation model to learn a single shared representation jointly across ECG, PPG, and PCG, built on a physiology-aware joint-embedding predictive architecture. The model maps heterogeneous waveforms into a common token space, processes them with a single shared Transformer encoder, and learns by predicting masked latent cardiac states, placing the pretraining target on shared physiology rather than sensor-specific waveform appearance. To handle the temporal offsets between electrical, mechanical, and hemodynamic events, cross-modal prediction uses a learned delay aligner tha"},{"id":"arxiv:2608.18565","source":"arxiv","title":"SemaPLC: A Project-Grounded, Verification-Gated Agent Harness for PLC Code Generation","authors":["Yanlun Tu","Huacan Wang","Ziyue Zhou","Jie Zhou","Ningyan Zhu","Ge Chen","Wangyi Chen","Tengfei Zhou","Yifan Zhou","Dasheng Yang","Xiaofeng Mou","Hui Zhang","Yi Xu"],"tags":["Code Agent","Evaluation"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.18565","url":"https://arxiv.org/abs/2608.18565","pdf":"https://arxiv.org/pdf/2608.18565.pdf","topics":["Code Agent","Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.18565","upvotes":110,"abstract":"Programmable logic controllers (PLCs) run industrial plants, and large language models can already generate independent program organization units (POUs) for them. Whether such logic integrates into an existing PLC project and then runs correctly has been checked only in limited tests. We present \\textsc{SemaPLC}, a project-grounded and verification-gated agent harness assembled from conventional tools but governed by a strict completion rule. Rather than stopping when the model judges its own output adequate, \\textsc{SemaPLC} declares a task complete only when logged external checks confirm it. Those checks cover the specification, the compilation, and the behavior on a live runtime. On 117 independent-POU tasks matching existing benchmarks, it attains the highest strict verified pass rate on all seven models (72.6\\% mean). On a project-context track of 65 tasks whose generated logic mu"},{"id":"arxiv:2608.19197","source":"arxiv","title":"SPADE: Self-Play in Adaptive Synthetic Executable Environments","authors":["Bo Liu","Simon Yu","Yiding Jiang","Ao Qu","Andrew Zhao","Zichen Liu","Junsu Kim","Zijian Zhou","Seungone Kim","Tongzheng Ren","Mickel Liu","Hanfei Yu","Zhaorun Chen","Weiyan Shi","Paul Pu Liang","Luke Zettlemoyer","Yejin Choi","Natasha Jaques"],"tags":["LLM Training","Tool Use","Reasoning","Evaluation","Reflection"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.19197","url":"https://arxiv.org/abs/2608.19197","pdf":"https://arxiv.org/pdf/2608.19197.pdf","topics":["LLM Training","Tool Use","Reasoning","Evaluation","Reflection"],"hfUrl":"https://huggingface.co/papers/2608.19197","upvotes":36,"abstract":"Continuous self-improvement requires an ever-expanding pool of self-generated, diverse, adaptive goals. For language agents, existing training environment pools (hand-curated, statically synthesized, or frozen-verifier) keep the goal distribution fixed as the learner scales. We introduce SPADE (Self-Play in Adaptive Synthetic Executable Environments), a self-play RL framework in which a single LLM plays two roles: an Environment Designer that writes complete, long-horizon training environments as executable code with an OpenAI Gym-style reset()/step() interface, and a Reasoning Agent that learns to act in them. Each is a stateful, multi-turn environment (state transitions, reward functions, and verification code), so one interface spans reasoning problems and multi-step agentic tool use. The Reasoning Agent's regret is estimated using the gap between its reward with and without privilege"},{"id":"arxiv:2608.18940","source":"arxiv","title":"Training Chemical Plausibility-Aware Large Language Models for Single-Step Retrosynthesis","authors":["Bogdan Zagribelnyy","Ivan Ilin","Nikita Bondarev","Maksim Kuznetsov","Mathieu Reymond","Vladimir Aladinskiy","Alex Aliper","Alex Zhavoronkov"],"tags":["Planning","Evaluation","Fine-tuning"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.18940","url":"https://arxiv.org/abs/2608.18940","pdf":"https://arxiv.org/pdf/2608.18940.pdf","topics":["Planning","Evaluation","Fine-tuning"],"hfUrl":"https://huggingface.co/papers/2608.18940","upvotes":27,"abstract":"Single-step retrosynthesis is a central component of computer-aided synthesis planning, yet its intrinsically one-to-many nature is poorly captured by single-answer evaluation and benchmarking protocols. To address this, we introduce Top-K prompting as a robust training and inference paradigm to better capture diverse, plausible reaction predictions. We compile CREED-CCV-2+USPTO-XL, an ultra-large-scale dataset of ~45.6 million verified reactions to train the C3LM (Chemistry Constraint-Consistent Language Model). By integrating fine-tuning with ChemCensor-based and novelty-oriented rewards, our model achieves state-of-the-art performance on the OOD URSA-expert-2026 benchmark. Further analysis of reaction uniqueness shows that LLMs and conventional models explore complementary reaction spaces, motivating ensemble-based retrosynthesis systems. Overall, our results establish Top-K, plausibi"},{"id":"arxiv:2608.18746","source":"arxiv","title":"Decision-Metric Alignment in Latent World Models: Diagnostics and Action-Conditioned Objectives for MPC Planning","authors":["Jiawei Wang","Ke Rui","Yushen Zuo","Yichun Feng","Minglei Li"],"tags":["Planning","Alignment","World Model"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.18746","url":"https://arxiv.org/abs/2608.18746","pdf":"https://arxiv.org/pdf/2608.18746.pdf","topics":["Planning","Alignment","World Model"],"hfUrl":"https://huggingface.co/papers/2608.18746","upvotes":15,"abstract":"JEPA-style latent world models can use Euclidean distance to a goal latent as the cost for model-predictive control (MPC). Strong decoding of task variables, however, does not guarantee that this particular cost ranks candidate action sequences by real task progress. We call the latter property \\emph{decision-metric alignment}. We introduce Plan-Real Spearman, which measures latent--real rank agreement on random plans, and CEM-stage Spearman, which measures the same agreement as cross-entropy-method (CEM) search concentrates its proposal. We analyze sufficient conditions under which latent distance preserves real-cost rankings, identifying encoder distortion, terminal rollout error, and candidate margins as the controlling quantities. Guided by the observed empirical alignment gap, DA-LeWM augments LeWM with inverse-dynamics and demonstration-conditioned goal-action heads. Across all our"},{"venue":"arXiv","id":"arxiv:2608.18423","source":"arxiv","title":"FM-Bench: A Benchmark for Long-Horizon Management with Competing Agents","authors":["Tianyou Wang","Chongyang Gao","Kezhen Chen","Chen Dong","Yinghao He","Donghan Li","Wangcheng Xu","Hongjiu Zhang","Chi Li"],"tags":["Evaluation"],"date":"2026-08-19","published":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.18423","url":"https://arxiv.org/abs/2608.18423","pdf":"https://arxiv.org/pdf/2608.18423.pdf","publicationKind":"preprint","topics":["Evaluation"],"hfUrl":"https://huggingface.co/papers/2608.18423","upvotes":12,"abstract":"Language model agents now execute bounded tasks reliably. Whether they can sustain effective decision-making over long horizons, where actions have cumulative consequences and the environment responds to their choices, remains largely unmeasured. FM-Bench (Football Management Benchmark) measures this. An LLM agent runs a football club for 20 in-game years through 26 tools and roughly 340 to 400 decision stops. It drafts a squad on the same budget as every rival, trades players, negotiates contracts, invests in facilities and youth, sets lineups, and answers to a board that can fire it, while a deterministic engine accumulates every year into one final score with no LLM judge or human rater. The solo track plays each of 15 frontier models against a frozen scripted world, and the Arena places the same models plus a scripted anchor in one shared 20-year world; to our knowledge, the first he"},{"id":"arxiv:2608.18852","source":"arxiv","title":"SkillGate: Training In-Policy Skill Selection in Long-Horizon Agents","authors":["Qingyao Li","Wenxiang Jiao","Shuai Shao","Kangning Zhang","Yuan Lu","Yi Guo","Weiwen Liu","Weinan Zhang","Yong Yu"],"tags":["Evaluation","Agent Framework"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.18852","url":"https://arxiv.org/abs/2608.18852","pdf":"https://arxiv.org/pdf/2608.18852.pdf","topics":["Evaluation","Agent Framework"],"hfUrl":"https://huggingface.co/papers/2608.18852","upvotes":1,"abstract":"Agent frameworks increasingly package procedural knowledge as skills: instruction files an agent reads on demand, while public libraries now hold thousands of them. Which skill to read has thus become a decision the policy itself makes in the middle of an episode, yet no existing signal trains it. We show that the default remedy, outcome-rewarded RL over the candidate slate, cannot teach it, for a structural reason we identify and name selector credit starvation: under a broadcast, sequence-level advantage, the few tokens that name the chosen skill carry a vanishing share of the loss, and the credit they inherit is increasingly wrong-signed as trajectories lengthen. A correct choice is punished whenever the execution after it fails, even though the choice itself is among the most valuable decisions in the trajectory. Auditing a completed run's own training artifacts confirms all three pr"},{"id":"arxiv:2608.18575","source":"arxiv","title":"Beyond LLM-Based Reasoning: Lightweight GNNs for Agent Failure Attribution","authors":["Ting-Wei Li","Yuanchen Bei","Xiao Lin","Hanghang Tong"],"tags":["Error Attribution","Post-Training","Multi-Agent","Reasoning","Evaluation"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.18575","url":"https://arxiv.org/abs/2608.18575","pdf":"https://arxiv.org/pdf/2608.18575.pdf","topics":["Error Attribution","Post-Training","Multi-Agent","Reasoning","Evaluation","Fine-tuning","Data Engine"],"upvotes":0,"abstract":"Large language model (LLM)-based multi-agent systems (MAS) often exhibit complex failure modes, which frequently cause agents to produce incorrect outcomes. This motivates the task of Agent Failure Attribution: given a failed multi-agent trajectory, identify the faulty agents and their corresponding error types. Existing approaches predominantly rely on LLMs to perform failure attribution, either through direct prompting, fine-tuning on synthetic data or complex agentic pipelines. While effective, these methods incur substantial computational overhead due to long-context processing, expensive post-training and handcrafted workflows. Moreover, empirical evidence shows that even state-of-the-art models achieve limited accuracy on existing benchmarks, suggesting that scaling model size alone is insufficient. In this work, we revisit this task and question the necessity of such expensive gen"},{"id":"arxiv:2608.16921","source":"arxiv","title":"MITRE-SAGE: A Multi-Agent Cybersecurity Question-Answering Model","authors":["Ali Habibzadeh","Farid Feyzi","Reza Ebrahimi Atani"],"tags":["Agentic Search","Multi-Agent","Hallucination","Evaluation","Interpretability"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.16921","url":"https://arxiv.org/abs/2608.16921","pdf":"https://arxiv.org/pdf/2608.16921.pdf","topics":["Agentic Search","Multi-Agent","Hallucination","Evaluation","Interpretability","Agent Framework"],"upvotes":0,"abstract":"Effective cybersecurity operations require timely and accurate analysis of large-scale heterogeneous security information; however, analysts increasingly struggle with information overload, alert fatigue, and time-constrained decision-making. Although large language models (LLMs) have demonstrated promising capabilities for question answering (QA), their effectiveness in cybersecurity remains limited by insufficient domain knowledge, a tendency to hallucinate, and difficulties in capturing both semantic and structural relationships. This work proposes MITRE-SAGE, a multi-agent retrieval-augmented generation framework that integrates semantic and structural cybersecurity knowledge to improve the reliability and interpretability of LLM-based QA systems. By decomposing complex tasks into query interpretation, evidence retrieval, and answer synthesis, MITRE-SAGE effectively supports cybersec"},{"id":"arxiv:2608.18627","source":"arxiv","title":"PCQA-R1: Advancing Generalized 3D Point Cloud Quality Assessment with Reinforcement Learning","authors":["Kangning Ye","Yunhao Li","Sijing Wu","Yucheng Zhu","Guangtao Zhai"],"tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.18627","url":"https://arxiv.org/abs/2608.18627","pdf":"https://arxiv.org/pdf/2608.18627.pdf","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"upvotes":0,"abstract":"No-reference point cloud quality assessment (PCQA) has been an active topic in recent years and is used to measure and optimize the visual experience of point clouds. However, large multimodal models (LMMs) have rarely been explored in this area. Previous LMM-based methods mainly rely on supervised fine-tuning to directly predict numerical quality scores, lacking the ability to generalize across datasets with heterogeneous MOS scales and limited annotations. A key difficulty is that absolute MOS regression can be brittle across datasets with different score scales and distortion distributions, whereas relative quality ranking is more stable under such shifts. In this paper, we present PCQA-R1, the first reinforcement learning LMM for 3D point cloud quality assessment to simultaneously model quality understanding and scoring. Built upon the group relative policy optimization (GRPO) strate"},{"id":"arxiv:2608.18881","source":"arxiv","title":"Falcon Perception-HD: High Density Perception via Reinforcement Learning","authors":["Sofian Chaybouti","Yasser Dahou","Ngoc Dung Huynh","Reda Alami","Hilde Kuehne"],"tags":["Post-Training","LLM Training","Evaluation","Fine-tuning","Data Engine"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.18881","url":"https://arxiv.org/abs/2608.18881","pdf":"https://arxiv.org/pdf/2608.18881.pdf","topics":["Post-Training","LLM Training","Evaluation","Fine-tuning","Data Engine"],"upvotes":0,"abstract":"Autoregressive perception models trained to localize visual entities under the open-vocabulary setting are mostly trained using Supervised fine-tuning (SFT) with maximum likelihood, yet it optimizes a proxy objective (per-token cross-entropy) that is fundamentally misaligned with perception metrics such as precision and recall. In this paper, we explore post-training reinforcement learning (RL), specifically GRPO, to directly align these models with their evaluation metrics. Building up on the recently introduced Falcon Perception, we design an RL framework that addresses perception-specific challenges: reward design for set-structured outputs and multi-head sampling control. We discover multiple benefits from RL for perception: first, RL unlocks state-of-the-art performance in very dense scenes (up to 500 objects per scene), a regime where most existing systems degrade sharply or collap"},{"id":"arxiv:2608.18884","source":"arxiv","title":"Training-Free Inference-Time Self-Reflection and Cost-Bounded Early Stopping for Large Language Models","authors":["Wei Yu","Suxing Liu","Minjie Yu","Jiahao Wang","Zhijian Zheng","Haocheng Deng","Bing Li"],"tags":["Post-Training","Multi-Agent","Reasoning","Evaluation","Reflection"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.18884","url":"https://arxiv.org/abs/2608.18884","pdf":"https://arxiv.org/pdf/2608.18884.pdf","topics":["Post-Training","Multi-Agent","Reasoning","Evaluation","Reflection"],"upvotes":0,"abstract":"Reinforcement-learning training of reasoning LLMs (e.g., GRPO) is expensive and requires a controllable environment, committing every contribution to a full training pipeline. We present EvoResearcher, a training-free, inference-time protocol that adds cost-bounded self-reflection to a single frozen LLM backbone. The protocol iterates generate -> self-critique -> revise until a maximum depth D is reached or the critique returns the CONFIRMED sentinel, an implicit early stop that lets the backbone self-verify its answer under a strict compute budget. Four self-reflective meta-reward components (correctness, efficiency, reflection depth, tool-call diversity) act as design principles instantiated as prompt-level mechanisms, so their benefits accrue with zero gradient updates. We validate the protocol on Big-Bench Hard (100 questions) and establish cross-domain behavior on GSM8K (500) and MA"},{"id":"arxiv:2608.18878","source":"arxiv","title":"DentAgent: Evidence-Centric Multi-Agent Coordination for Multimodal Dental Reasoning","authors":["Zijie Meng","Xiwei Dai","Yixuan Tang","Jin Hao","Yang Feng","Fudong Zhu","Xiaoqiang Liu","Shaosheng Cao","Zuozhu Liu"],"tags":["VLM Training","Multi-Agent","Reasoning","Evaluation","Agent Framework"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.18878","url":"https://arxiv.org/abs/2608.18878","pdf":"https://arxiv.org/pdf/2608.18878.pdf","topics":["VLM Training","Multi-Agent","Reasoning","Evaluation","Agent Framework"],"upvotes":0,"abstract":"Oral diseases affect billions of people worldwide, underscoring a pressing need for accurate and reliable dental assessment that integrates heterogeneous evidence from domain knowledge, radiographs, intraoral photographs, and 3D dental data. Most existing dental AI systems remain modality- or task-specific. Although recent vision-language models support flexible dental question answering, directly generated response leaves evidence implicit and untraceable. To address these limitations, we introduce DentAgent, an evidence-centric multi-agent framework, in which the Orchestrator coordinate five specialized agents spanning various modalities. Each specialist utilizes domain tools to convert observations into structured evidence records. The Evidence Blackboard manages these records as a shared evidence state, tracking coverage, gaps, and conflicts before response generation. This standardi"},{"id":"arxiv:2608.19029","source":"arxiv","title":"Adaptive Memory and Reflection Multi-Agent System for Medical Question Answering","authors":["Pradeep Murugesan","Luoxiao Yang","Xueli Chen","Xinqi Fan"],"tags":["Multi-Agent","Reasoning","Evaluation","Reflection","Agent Framework"],"date":"2026-08-19","arxiv":"https://arxiv.org/abs/2608.19029","url":"https://arxiv.org/abs/2608.19029","pdf":"https://arxiv.org/pdf/2608.19029.pdf","topics":["Multi-Agent","Reasoning","Evaluation","Reflection","Agent Framework"],"upvotes":0,"abstract":"Accurate and responsible medical question answering (QA) is important in healthcare, where complex cases require factual knowledge and nuanced reasoning. Existing medical QA systems, typically based on single-agent architectures and static retrieval, often lack adaptability, persistent memory, and structured decision-making. This work introduces an adaptive memory and reflection (AMR) agentic system, a multi-agent framework in which specialized agents use dedicated memory and reflection-based feedback to retrieve relevant prior cases and improve subsequent reasoning. Complexity assessment routes questions through solo, collaborative, or escalated workflows, while consensus and ethical overseer modules support reasoning consolidation and output review. Evaluation on MedQA and MedMCQA demonstrates strong performance compared with several baselines. Ablation studies show that combining agen"}],"archive":[],"latestPath":"data/latest.json"};
